from collections import deque


def solve(nums, k):
    window, out = deque(), []  # indices whose values decrease from front to back
    for i, x in enumerate(nums):
        while window and nums[window[-1]] <= x:
            window.pop()
        window.append(i)
        if window[0] <= i - k:
            window.popleft()
        if i >= k - 1:
